"""Error text shared by the command handlers and the argument parser."""
import os


class Exit(Exception):
    def __init__(self, status=0, text='', stream='stderr'):
        super().__init__(text)
        self.status, self.text, self.stream = status, text, stream


def fail(message, *causes):
    text = 'zoxide: ' + message
    if len(causes) == 1:
        text += '\n\nCaused by:\n    ' + str(causes[0]).replace('\n', '\n    ')
    elif causes:
        text += '\n\nCaused by:\n' + '\n'.join(
            f'    {index}: ' + str(cause).replace('\n', '\n       ')
            for index, cause in enumerate(causes))
    raise Exit(1, text + '\n')


def os_error(error):
    return f'{os.strerror(error.errno)} (os error {error.errno})'
