"""Numeric parsing and score formatting without locale-dependent conversions."""
import math
import re

_FLOAT = re.compile(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)', re.I)
_UINT = re.compile(r'\+?[0-9]+')


def parse_float(text):
    if not text:
        raise ValueError('cannot parse float from empty string')
    if _FLOAT.fullmatch(text) is None:
        raise ValueError('invalid float literal')
    return float(text)


def parse_uint(text, bits=64):
    if not text:
        raise ValueError('cannot parse integer from empty string')
    if _UINT.fullmatch(text) is None:
        raise ValueError('invalid digit found in string')
    try:
        value = int(text)
    except ValueError:
        raise ValueError('number too large to fit in target type') from None
    if value >= 1 << bits:
        raise ValueError('number too large to fit in target type')
    return value


def nonnegative(value):
    # The update operation treats an unordered value like a zero increment.
    return value if value > 0.0 else 0.0


def frecency(rank, accessed, now):
    elapsed = max(0, now - accessed)
    if elapsed < 3600:
        return rank * 4.0
    if elapsed < 86400:
        return rank * 2.0
    if elapsed < 604800:
        return rank * 0.5
    return rank * 0.25


def score_text(score):
    if math.isnan(score):
        return '   NaN'
    score = max(0.0, min(9999.0, score))
    return f'{score:6.1f}'
