"""Path normalization and exclusion patterns."""
import os
import pwd
import re
from .errors import fail, os_error


def home_dir():
    home = os.environ.get('HOME')
    if home:
        return home
    try:
        return pwd.getpwuid(os.getuid()).pw_dir
    except KeyError:
        return None


def data_dir():
    if '_ZO_DATA_DIR' in os.environ:
        path = os.environ['_ZO_DATA_DIR']
        if not path.startswith('/'):
            fail('_ZO_DATA_DIR must be an absolute path')
        return path
    xdg = os.environ.get('XDG_DATA_HOME', '')
    if xdg.startswith('/'):
        return os.path.join(xdg, 'zoxide')
    home = home_dir()
    if home is None:
        fail('could not find data directory')
    return os.path.join(home, '.local', 'share', 'zoxide')


def normalize(path, resolve=None):
    if resolve is None:
        resolve = os.environ.get('_ZO_RESOLVE_SYMLINKS') == '1'
    if resolve:
        try:
            return os.path.realpath(path, strict=True)
        except OSError as e:
            fail('could not resolve path: ' + path, os_error(e))
    try:
        if not path.startswith('/'):
            path = os.path.join(os.getcwd(), path)
    except OSError as e:
        fail('could not get current directory', os_error(e))
    # Unlike POSIX normpath, a double leading slash has no special meaning here.
    return '/' + os.path.normpath(path).lstrip('/')


def components(path):
    parts = path.split('/')
    result = ['/'] if path.startswith('/') else (['.'] if parts and parts[0] == '.' else [])
    result.extend(part for part in parts if part not in ('', '.'))
    return result


def within(path, base):
    a, b = components(path), components(base)
    return a[:len(b)] == b


def directory_exists(path):
    try:
        return os.path.isdir(path)
    except (ValueError, OSError):
        return False


class Exclusions:
    """Whole-path, case-sensitive shell globs, with recursive components."""
    def __init__(self):
        spec = os.environ.get('_ZO_EXCLUDE_DIRS')
        if spec is None:
            spec = home_dir() or ''
        self.patterns = []
        for pattern in spec.split(':'):
            self.patterns.append(self._compile(pattern))

    @staticmethod
    def _error(pattern, index, message):
        fail('invalid glob in _ZO_EXCLUDE_DIRS: ' + pattern,
             f'Pattern syntax error near position {index}: {message}')

    def _compile(self, pattern):
        tokens = []
        i = 0
        while i < len(pattern):
            ch = pattern[i]
            if ch == '*':
                end = i
                while end < len(pattern) and pattern[end] == '*':
                    end += 1
                count = end - i
                if count > 2:
                    self._error(pattern, i + 2, 'wildcards are either regular `*` or recursive `**`')
                if count == 2:
                    if i and pattern[i - 1] != '/':
                        self._error(pattern, i - 1, 'recursive wildcards must form a single path component')
                    if end < len(pattern) and pattern[end] != '/':
                        self._error(pattern, end, 'recursive wildcards must form a single path component')
                    if end < len(pattern):
                        tokens.append('(?:.*/)?')
                        end += 1
                    else:
                        tokens.append('.*')
                else:
                    tokens.append('.*')
                i = end
                continue
            if ch == '?':
                tokens.append('.')
            elif ch == '[':
                start = i
                j = i + 1
                negate = j < len(pattern) and pattern[j] == '!'
                if negate:
                    j += 1
                content_start = j
                if j < len(pattern) and pattern[j] == ']':
                    j += 1
                while j < len(pattern) and pattern[j] != ']':
                    j += 1
                if j == len(pattern) or j == content_start:
                    self._error(pattern, start, 'invalid range pattern')
                content = pattern[content_start:j]
                choices = []
                k = 0
                while k < len(content):
                    if k + 2 < len(content) and content[k + 1] == '-':
                        lo, hi = content[k], content[k + 2]
                        if ord(lo) <= ord(hi):
                            choices.append(re.escape(lo) + '-' + re.escape(hi))
                        k += 3
                    else:
                        choices.append(re.escape(content[k]))
                        k += 1
                if choices:
                    tokens.append('[' + ('^' if negate else '') + ''.join(choices) + ']')
                else:
                    tokens.append('.' if negate else '(?!)')
                i = j
            else:
                tokens.append(re.escape(ch))
            i += 1
        return re.compile(''.join(tokens), re.S)

    def excludes(self, path):
        return ('\n' in path or '\r' in path or
                any(pattern.fullmatch(path) is not None for pattern in self.patterns))
