                    tokens.append('[' + ('^' if negate else '') + ''.join(choices) + ']')
                else:
                    tokens.append('.' if negate else '(?!)')
                i = j
            else:
                tokens.append(re.escape(ch))
            i += 1
        return re.compile(''.join(tokens), re.S)

    def excludes(self, path):
        return ('\n' in path or '\r' in path or
                any(pattern.fullmatch(path) is not None for pattern in self.patterns))
