"""Persistent directory records and their on-disk representation.

A record has a UTF-8 path, a floating point rank, and an epoch in seconds.
The file is replaced atomically so readers never see a partial update.
"""
from dataclasses import dataclass
import math
import os
import struct
import tempfile
from .errors import fail, os_error
from .numbers import frecency, nonnegative
from .paths import data_dir


@dataclass
class Entry:
    path: str
    rank: float
    accessed: int

    def score(self, now):
        return frecency(self.rank, self.accessed, now)


class Database:
    def __init__(self):
        self.directory = data_dir()
        self.path = os.path.join(self.directory, 'db.zo')
        self.entries = []
        self.dirty = False
        try:
            with open(self.path, 'rb') as handle:
                content = handle.read()
        except FileNotFoundError:
            return
        except OSError as e:
            fail('could not read from database: ' + self.path, os_error(e))
        self.entries = self.decode(content)

    @staticmethod
    def decode(data):
        if len(data) < 4:
            fail('could not deserialize database: corrupted data')
        version = struct.unpack_from('<I', data)[0]
        if version != 3:
            fail(f'unsupported version (got {version}, supports 3)')
        pos = 4

        def take(size):
            nonlocal pos
            if size > len(data) - pos:
                fail('could not deserialize database', 'io error: unexpected end of file')
            item = data[pos:pos + size]
            pos += size
            return item

        count, = struct.unpack('<Q', take(8))
        records = []
        for _ in range(count):
            length, = struct.unpack('<Q', take(8))
            raw = take(length)
            try:
                path = raw.decode('utf-8')
            except UnicodeDecodeError as e:
                if e.reason == 'unexpected end of data':
                    description = f'incomplete utf-8 byte sequence from index {e.start}'
                else:
                    description = f'invalid utf-8 sequence of {e.end - e.start} bytes from index {e.start}'
                fail('could not deserialize database', description)
            rank, accessed = struct.unpack('<dQ', take(16))
            records.append(Entry(path, rank, accessed))
        if pos != len(data):
            fail('could not deserialize database', 'Slice had bytes remaining after deserialization')
        return records

    def encode(self):
        pieces = [struct.pack('<IQ', 3, len(self.entries))]
        for entry in self.entries:
            path = entry.path.encode('utf-8')
            pieces.extend((struct.pack('<Q', len(path)), path,
                           struct.pack('<dQ', entry.rank, entry.accessed)))
        return b''.join(pieces)

    def save(self):
        if not self.dirty:
            return
        try:
            os.makedirs(self.directory, exist_ok=True)
        except OSError as e:
            fail('could not create data directory: ' + self.directory, os_error(e))
        temp = None
        try:
            # Respect the caller's umask for the final database.
            for _ in range(10):
                temp = os.path.join(self.directory, '.db.' + os.urandom(8).hex() + '.tmp')
                try:
                    fd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o666)
                    break
                except FileExistsError:
                    continue
            else:
                raise FileExistsError(17, 'File exists')
            with os.fdopen(fd, 'wb') as handle:
                handle.write(self.encode())
            os.replace(temp, self.path)
        except OSError as e:
            fail('could not write to database: ' + self.path, os_error(e))
        finally:
            if temp is not None:
                try:
                    os.unlink(temp)
                except OSError:
                    pass
        self.dirty = False

    def find(self, path):
        return next((i for i, entry in enumerate(self.entries) if entry.path == path), None)

    def increment(self, path, amount, now, update_time=True):
        index = self.find(path)
        if index is None:
            self.entries.append(Entry(path, nonnegative(amount), now))
        else:
            entry = self.entries[index]
            entry.rank = nonnegative(entry.rank + amount)
            if update_time:
                entry.accessed = now
        self.dirty = True

    def remove(self, index):
        last = self.entries.pop()
        if index < len(self.entries):
            self.entries[index] = last
        self.dirty = True

    def age(self, max_age):
        total = sum(entry.rank for entry in self.entries)
        if total > max_age:
            factor = 0.9 * max_age / total
            for entry in self.entries:
                entry.rank *= factor
            self.entries = [entry for entry in self.entries if not entry.rank < 1.0]
            self.dirty = True

    def sort(self, now):
        if len(self.entries) < 2:
            return
        # Stable ascending comparisons, followed by reverse traversal, give the
        # most recently inserted entry priority when scores are equal.
        # An unordered score compares below ordinary scores.
        self.entries.sort(key=lambda entry: (not math.isnan(entry.score(now)),
                                             entry.score(now)))
        self.dirty = True
