"""Command-line grammar and presentation."""
import os
from dataclasses import dataclass
from importlib.resources import files
from .errors import Exit
from .numbers import parse_float
from .shells import SHELLS, HOOKS

COMMANDS = ('add', 'edit', 'import', 'init', 'query', 'remove')
EDIT_COMMANDS = ('reload', 'delete', 'increment', 'decrement')
FOOTER = "For more information, try '--help'.\n"

# name: (short spelling, value label, value kind)
SPECS = {
    'add': {'score': ('s', 'SCORE', 'float')},
    'edit': {},
    'import': {'from': (None, 'FROM', ('autojump', 'z')), 'merge': (None, None, None)},
    'init': {'no-cmd': (None, None, None), 'cmd': (None, 'CMD', 'string'),
             'hook': (None, 'HOOK', HOOKS)},
    'query': {'all': ('a', None, None), 'interactive': ('i', None, None),
              'list': ('l', None, None), 'score': ('s', None, None),
              'exclude': (None, 'path', 'string'), 'base-dir': (None, 'path', 'string')},
    'remove': {},
}
GENERAL = {'help': ('h', None, None), 'version': ('V', None, None)}


@dataclass
class Invocation:
    command: tuple
    options: dict
    arguments: list


def similarity(a, b):
    """Jaro similarity for spelling suggestions."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    distance = max(len(a), len(b)) // 2 - 1
    distance = max(0, distance)
    amatch = [False] * len(a)
    bmatch = [False] * len(b)
    matches = 0
    for i, char in enumerate(a):
        for j in range(max(0, i - distance), min(len(b), i + distance + 1)):
            if not bmatch[j] and char == b[j]:
                amatch[i], bmatch[j] = True, True
                matches += 1
                break
    if not matches:
        return 0.0
    aa = [a[i] for i in range(len(a)) if amatch[i]]
    bb = [b[i] for i in range(len(b)) if bmatch[i]]
    transpositions = sum(x != y for x, y in zip(aa, bb)) / 2.0
    return (matches / len(a) + matches / len(b) + (matches - transpositions) / matches) / 3.0


def suggestion(value, choices):
    best = None
    quality = 0.7
    for choice in choices:
        s = similarity(value, choice)
        if s > quality:
            best, quality = choice, s
    return best


class Parser:
    def __init__(self, program):
        self.program = program
        self.command = ()
        self.options = {}
        self.arguments = []
        self.option_order = []

    def specs(self):
        spec = SPECS.get(self.command[0], {}) if len(self.command) == 1 else {}
        return dict(spec, **GENERAL)

    def label(self, name):
        value = self.specs()[name][1]
        return '--' + name + (f' <{value}>' if value else '')

    def help(self, status=0):
        name = '_'.join(self.command or ('main',))
        text = files('zore').joinpath('help', name + '.txt').read_text()
        raise Exit(status, text.replace('@PROGRAM@', self.program), 'stderr' if status else 'stdout')

    def version(self):
        name = '-'.join(('zoxide',) + self.command)
        raise Exit(0, f'{name} 0.9.9\n', 'stdout')

    def usage(self, selected=None, positional_used=False, basic=False):
        parts = [self.program, *self.command]
        if not self.command:
            return ' '.join(parts + ['<COMMAND>'])
        name = self.command[0]
        if len(self.command) == 2:
            if self.command[1] != 'reload':
                parts.append('<PATH>')
            return ' '.join(parts)
        if selected is None:
            if name in ('add', 'import', 'init', 'query'):
                parts.append('[OPTIONS]')
        else:
            seen = set()
            for option in selected:
                if option not in seen:
                    parts.append(self.label(option))
                    seen.add(option)
        if name == 'add':
            parts.append('<PATHS>...')
        elif name == 'import':
            if selected is None or 'from' not in selected:
                parts.extend(('--from', '<FROM>'))
            parts.append('<PATH>')
        elif name == 'init':
            parts.append('<SHELL>')
        elif name == 'query':
            parts.append('<KEYWORDS>...' if positional_used else '[KEYWORDS]...')
        elif name == 'remove':
            parts.append('<PATHS>...' if positional_used else '[PATHS]...')
        return ' '.join(parts)

    def error(self, message, usage=None, tips=None):
        text = 'error: ' + message + '\n'
        if tips:
            text += '\n' + '\n'.join('  tip: ' + tip for tip in tips) + '\n'
        if usage:
            text += '\nUsage: ' + usage + '\n'
        text += '\n' + FOOTER
        raise Exit(2, text)

    def unrecognized(self, value, choices):
        nearest = suggestion(value, choices)
        tips = [f"a similar subcommand exists: '{nearest}'"] if nearest else []
        self.error(f"unrecognized subcommand '{value}'", self.usage(), tips)

    def unexpected(self, value):
        tips = []
        suggested = None
        if value.startswith('--'):
            value = value.split('=', 1)[0]
            suggested = suggestion(value[2:], self.specs())
            if suggested:
                tips.append(f"a similar argument exists: '--{suggested}'")
        if not suggested and value.startswith('-') and self.has_positionals():
            tips.append(f"to pass '{value}' as a value, use '-- {value}'")
        used = [*self.option_order, suggested] if suggested else None
        self.error(f"unexpected argument '{value}' found",
                   self.usage(selected=used, positional_used=bool(self.arguments) if suggested else False), tips)

    def has_positionals(self):
        return bool(self.command) and (self.command[0] != 'edit' or
                                        (len(self.command) == 2 and self.command[1] != 'reload'))

    def missing_value(self, label, kind=None):
        message = f"a value is required for '{label}' but none was supplied"
        if isinstance(kind, tuple):
            message += '\n  [possible values: ' + ', '.join(kind) + ']'
        self.error(message)

    def value(self, text, label, kind):
        if isinstance(kind, tuple):
            if not text:
                self.missing_value(label, kind)
            if text not in kind:
                message = f"invalid value '{text}' for '{label}'\n  [possible values: {', '.join(kind)}]"
                nearest = suggestion(text, kind)
                self.error(message, tips=[f"a similar value exists: '{nearest}'"] if nearest else None)
        elif kind == 'float':
            try:
                return parse_float(text)
            except ValueError as e:
                self.error(f"invalid value '{text}' for '{label}': {e}")
        elif kind == 'nonempty' and not text:
            self.missing_value(label)
        return text

    def recognized_flag(self, text):
        specs = self.specs()
        if text.startswith('--'):
            return text[2:].split('=', 1)[0] in specs
        return len(text) > 1 and any(s[0] == text[1] for s in specs.values())

    def set_option(self, name, attached, args, index):
        # Return the index immediately after all the consumed tokens.
        if name == 'help':
            self.help()
        if name == 'version':
            self.version()
        spec = self.specs()[name]
        if name in self.options:
            self.error(f"the argument '{self.label(name)}' cannot be used multiple times", self.usage())
        if spec[1] is None:
            if attached is not None:
                self.error(f"unexpected value '{attached}' for '--{name}' found; no more were expected",
                           self.usage(selected=[*self.option_order, name], positional_used=bool(self.arguments)))
            value = True
        else:
            if attached is None:
                if index >= len(args):
                    self.missing_value(self.label(name), spec[2])
                text = args[index]
                if len(text) > 1 and text.startswith('-'):
                    if text == '--' or self.recognized_flag(text):
                        self.missing_value(self.label(name), spec[2])
                    self.unexpected(text if text.startswith('--') else text[:2])
                attached = text
                index += 1
            value = self.value(attached, self.label(name), spec[2])
        self.options[name] = value
        self.option_order.append(name)
        return index

    def positional(self, text):
        if not self.command:
            if text not in COMMANDS:
                self.unrecognized(text, COMMANDS)
            self.command = (text,)
            return
        if self.command == ('edit',):
            if text not in EDIT_COMMANDS:
                self.unrecognized(text, ())
            self.command += (text,)
            return
        if not self.has_positionals():
            self.unexpected(text)
        name = self.command[0]
        if name in ('init', 'import', 'edit') and self.arguments:
            self.unexpected(text)
        if name == 'init':
            text = self.value(text, '<SHELL>', SHELLS)
        elif name in ('add', 'import'):
            self.value(text, '<PATHS>...' if name == 'add' else '<PATH>', 'nonempty')
        self.arguments.append(text)

    def parse(self, args):
        index, trailing = 0, False
        while index < len(args):
            text = args[index]
            index += 1
            if text == '--' and not trailing:
                trailing = True
                continue
            if not trailing and len(text) > 1 and text.startswith('-'):
                specs = self.specs()
                if text.startswith('--'):
                    option = text[2:]
                    attached = None
                    if '=' in option:
                        option, attached = option.split('=', 1)
                    if option not in specs:
                        self.unexpected(text)
                    index = self.set_option(option, attached, args, index)
                else:
                    j = 1
                    while j < len(text):
                        char = text[j]
                        option = next((key for key, value in specs.items() if value[0] == char), None)
                        if option is None:
                            self.unexpected('-' + char)
                        attached = None
                        if specs[option][1] is not None and j + 1 < len(text):
                            attached = text[j + 1:]
                            if attached.startswith('='):
                                attached = attached[1:]
                        index = self.set_option(option, attached, args, index)
                        if specs[option][1] is not None:
                            break
                        j += 1
            else:
                self.positional(text)
        if not self.command:
            self.help(2)
        if self.command == ('query',) and self.options.get('interactive') and self.options.get('list'):
            pair = [name for name in self.option_order if name in ('interactive', 'list')]
            selected = [name for name in self.option_order if name != pair[1]]
            self.error(f"the argument '--{pair[0]}' cannot be used with '--{pair[1]}'",
                       self.usage(selected=selected, positional_used=bool(self.arguments)))
        missing = []
        name = self.command[0]
        if name == 'import' and 'from' not in self.options:
            missing.append('--from <FROM>')
        if not self.arguments:
            if name == 'add':
                missing.append('<PATHS>...')
            elif name == 'init':
                missing.append('<SHELL>')
            elif name == 'import' or (len(self.command) == 2 and self.command[1] != 'reload'):
                missing.append('<PATH>')
        if missing:
            self.error('the following required arguments were not provided:\n' +
                       '\n'.join('  ' + item for item in missing),
                       self.usage(selected=self.option_order))
        return Invocation(self.command, self.options, self.arguments)


def parse(args, program):
    return Parser(program).parse(args)
