"""The optional selector interface. No selector is required for normal queries."""
import os
import subprocess
from .errors import fail, Exit, os_error

PREFIX = ['--delimiter=\t', '--nth=2', '--read0']
PREVIEW = [r'--preview=\command -p ls -Cp --color=always --group-directories-first {2..}',
           '--preview-window=down,30%,sharp']
QUERY_OPTIONS = [
    '--exact', '--no-sort', '--bind=ctrl-z:ignore,btab:up,tab:down',
    '--cycle', '--keep-right', '--border=sharp', '--height=45%',
    '--info=inline', '--layout=reverse', '--tabstop=1', '--exit-0', *PREVIEW,
]
EDIT_OPTIONS = [
    '--exact', '--no-sort',
    '--bind=btab:up,ctrl-r:reload(zoxide edit reload),ctrl-d:reload(zoxide edit delete {2..}),'
    'ctrl-w:reload(zoxide edit increment {2..}),ctrl-s:reload(zoxide edit decrement {2..}),'
    'ctrl-z:ignore,double-click:ignore,enter:abort,start:reload(zoxide edit reload),tab:down',
    '--cycle', '--keep-right', '--border=sharp', '--border-label=  zoxide-edit  ',
    '--header=ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH',
    '--info=inline', '--layout=reverse', '--padding=1,0,0,0', '--color=label:bold',
    '--tabstop=1', *PREVIEW,
]


class Selector:
    def __init__(self, edit=False):
        env = os.environ.copy()
        options = list(PREFIX)
        if '_ZO_FZF_OPTS' in env:
            env['FZF_DEFAULT_OPTS'] = env['_ZO_FZF_OPTS']
        else:
            options += EDIT_OPTIONS if edit else QUERY_OPTIONS
        try:
            self.process = subprocess.Popen(['fzf', *options], stdin=subprocess.PIPE,
                                            stdout=subprocess.PIPE, env=env)
        except FileNotFoundError:
            fail('could not find fzf, is it installed?')
        except OSError as e:
            fail('could not start fzf', os_error(e))

    def select(self, data):
        try:
            output, _ = self.process.communicate(data)
        except OSError as e:
            fail('could not communicate with fzf', os_error(e))
        status = self.process.returncode
        if status == 0:
            return output
        if status == 130:
            raise Exit(130)
        if status == 1:
            fail('no match found')
        fail('fzf returned an error')
