"""Directory database command implementations."""
import math
import os
import time
from .database import Database, Entry
from .errors import fail, os_error, Exit
from .interactive import Selector
from .numbers import parse_float, parse_uint, score_text
from .paths import Exclusions, directory_exists, normalize, within
from .shells import render


def add(paths, options):
    excluded = Exclusions()
    normalized = []
    for path in paths:
        path = normalize(path)
        if excluded.excludes(path):
            continue
        if not directory_exists(path):
            fail('not a directory: ' + path)
        normalized.append(path)
    db = Database()
    now = int(time.time())
    for path in normalized:
        db.increment(path, options.get('score', 1.0), now)
    raw_max_age = os.environ.get('_ZO_MAXAGE', '10000')
    try:
        max_age = parse_uint(raw_max_age)
    except ValueError as e:
        fail('unable to parse _ZO_MAXAGE as integer: ' + raw_max_age, e)
    db.age(max_age)
    db.save()
    return b''


def remove(paths):
    db = Database()
    for path in paths:
        index = db.find(path)
        if index is None:
            try:
                normalized = normalize(path)
            except Exit:
                normalized = None
            if normalized is not None:
                index = db.find(normalized)
        if index is None:
            fail('path not found in database: ' + path)
        db.remove(index)
    db.save()
    return b''


def import_entries(path, options):
    db = Database()
    if db.entries and not options.get('merge'):
        fail('current database is not empty, specify --merge to continue anyway')
    try:
        with open(path, 'rb') as handle:
            raw = handle.read()
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        fail('could not open database for importing: ' + path, 'stream did not contain valid UTF-8')
    except OSError as e:
        fail('could not open database for importing: ' + path, os_error(e))
    entries = list(db.entries)
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if not line:
            continue
        if options['from'] == 'z':
            parts = line.rsplit('|', 2)
            epoch_text = parts[-1]
            try:
                accessed = parse_uint(epoch_text)
            except ValueError as e:
                fail('import error', 'invalid epoch: ' + epoch_text, e)
            if len(parts) < 2:
                fail('import error', 'invalid entry: ' + line)
            rank_text = parts[-2]
            try:
                rank = parse_float(rank_text)
            except ValueError as e:
                fail('import error', 'invalid rank: ' + rank_text, e)
            if len(parts) < 3:
                fail('import error', 'invalid entry: ' + line)
            entry_path = parts[0]
        else:
            parts = line.split('\t', 1)
            if len(parts) != 2:
                fail('import error', 'invalid entry: ' + line)
            rank_text, entry_path = parts
            try:
                weight = parse_float(rank_text)
            except ValueError as e:
                fail('import error', 'invalid rank: ' + rank_text, e)
            try:
                rank = 1.0 / (1.0 + math.exp(-weight))
            except OverflowError:
                rank = 0.0
            accessed = 0
        entries.append(Entry(entry_path, rank, accessed))
    entries.sort(key=lambda entry: entry.path)
    merged = []
    for entry in entries:
        if merged and entry.path == merged[-1].path:
            merged[-1].rank += entry.rank
            merged[-1].accessed = max(merged[-1].accessed, entry.accessed)
        else:
            merged.append(Entry(entry.path, entry.rank, entry.accessed))
    if merged != db.entries or entries:
        db.dirty = True
    db.entries = merged
    db.save()
    return b''


def keyword_match(path, keywords):
    if not keywords:
        return True
    lower = path.lower()
    position = 0
    for keyword in keywords[:-1]:
        found = lower.find(keyword, position)
        if found < 0:
            return False
        position = found + len(keyword)
    final = keywords[-1]
    found = lower.rfind(final, position)
    return found >= 0 and '/' not in lower[found + len(final):]


def encode_record(entry, now, show_score=False, interactive=False):
    path = entry.path.encode('utf-8')
    if interactive:
        return score_text(entry.score(now)).encode() + b'\t' + path + b'\0'
    if show_score:
        return score_text(entry.score(now)).encode() + b' ' + path + b'\n'
    return path + b'\n'


def query(keywords, options):
    db = Database()
    excluded = Exclusions()
    now = int(time.time())
    keywords = [keyword.lower() for keyword in keywords]
    db.sort(now)
    selector = Selector() if options.get('interactive') else None
    listing = options.get('list') or selector is not None
    results = []
    deletions = set()
    matched_current = False
    for index in range(len(db.entries) - 1, -1, -1):
        entry = db.entries[index]
        if not keyword_match(entry.path, keywords):
            continue
        if 'base-dir' in options and not within(entry.path, options['base-dir']):
            continue
        if excluded.excludes(entry.path):
            deletions.add(index)
            continue
        if not options.get('all') and not directory_exists(entry.path):
            if now - entry.accessed > 90 * 86400:
                deletions.add(index)
            continue
        if entry.path == options.get('exclude'):
            matched_current = True
            continue
        results.append(entry)
        if not listing:
            break
    if deletions:
        db.entries = [entry for index, entry in enumerate(db.entries) if index not in deletions]
        db.dirty = True
    db.save()
    if selector is not None:
        data = b''.join(encode_record(entry, now, interactive=True) for entry in results)
        output = selector.select(data)
        if options.get('score'):
            return output
        if len(output) < 7:
            fail('could not read selection from fzf')
        return output[7:]
    if not listing and not results:
        if matched_current:
            fail('you are already in the only match')
        fail('no match found')
    return b''.join(encode_record(entry, now, options.get('score', False)) for entry in results)


def edit(subcommand, paths):
    db = Database()
    now = int(time.time())
    if subcommand is None:
        Selector(edit=True).select(b'')
        return b''
    if subcommand in ('increment', 'decrement'):
        db.increment(paths[0], 1.0 if subcommand == 'increment' else -1.0, now, update_time=False)
    elif subcommand == 'delete':
        index = db.find(paths[0])
        if index is not None:
            db.remove(index)
    db.save()
    return b''.join(encode_record(entry, now, interactive=True) for entry in reversed(db.entries))


def execute(invocation):
    name = invocation.command[0]
    options, args = invocation.options, invocation.arguments
    if name == 'init':
        return render(args[0], options.get('hook', 'pwd'), options.get('cmd', 'z'),
                      options.get('no-cmd', False)).encode('utf-8')
    if name == 'add':
        return add(args, options)
    if name == 'remove':
        return remove(args)
    if name == 'import':
        return import_entries(args[0], options)
    if name == 'query':
        return query(args, options)
    if name == 'edit':
        return edit(invocation.command[1] if len(invocation.command) > 1 else None, args)
    return b''
