"""Executable entry point."""
import os
import sys
from .cli import parse
from .commands import execute
from .errors import Exit


def main():
    status = 0
    try:
        invocation = parse(sys.argv[1:], os.path.basename(sys.argv[0]) or 'executable')
        result = execute(invocation)
        sys.stdout.buffer.write(result)
        sys.stdout.buffer.flush()
    except Exit as e:
        status = e.status
        if e.text:
            stream = sys.stdout if e.stream == 'stdout' else sys.stderr
            stream.buffer.write(e.text.encode('utf-8', errors='replace'))
            stream.buffer.flush()
    except BrokenPipeError:
        # Avoid emitting an interpreter traceback when a pipeline closes early.
        status = 1
        try:
            fd = os.open(os.devnull, os.O_WRONLY)
            os.dup2(fd, sys.stdout.fileno())
            os.close(fd)
        except OSError:
            pass
    except KeyboardInterrupt:
        status = 130
    raise SystemExit(status)
