use std::slice;

struct Record {
    path: String,
    value: f64,
    index: u64,
}

#[no_mangle]
pub unsafe extern "C" fn order_scores(values: *const f64, len: usize, output: *mut u64) {
    let mut records: Vec<Record> = slice::from_raw_parts(values, len)
        .iter().enumerate().map(|(i, value)| Record {
            path: String::new(), value: *value, index: i as u64,
        }).collect();
    records.sort_unstable_by(|a, b| a.value.total_cmp(&b.value));
    let output = slice::from_raw_parts_mut(output, len);
    for (slot, record) in output.iter_mut().zip(records) {
        *slot = record.index;
    }
}

#[no_mangle]
pub unsafe extern "C" fn order_paths(
    strings: *const *const u8, lengths: *const usize, len: usize, output: *mut u64,
) {
    let strings = slice::from_raw_parts(strings, len);
    let lengths = slice::from_raw_parts(lengths, len);
    let mut records: Vec<Record> = strings.iter().zip(lengths).enumerate()
        .map(|(i, (pointer, length))| Record {
            path: String::from_utf8_unchecked(slice::from_raw_parts(*pointer, *length).to_vec()),
            value: 0.0,
            index: i as u64,
        }).collect();
