"""Ordering of directory records, including IEEE floating-point special values."""
import ctypes
import os
import struct
import tempfile
from importlib.resources import files

_LIBRARY = None


def _library():
    global _LIBRARY
    if _LIBRARY is None:
        # The built archive is self-contained. A temporary, unlinked shared
        # object supplies the standard-library ordering kernel.
        data = files('zore').joinpath('_order.so').read_bytes()
        fd, path = tempfile.mkstemp(prefix='zo-order-', suffix='.so')
        try:
            with os.fdopen(fd, 'wb') as handle:
                handle.write(data)
            lib = ctypes.CDLL(path)
        finally:
            os.unlink(path)
        lib.order_scores.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t,
                                      ctypes.POINTER(ctypes.c_uint64)]
        lib.order_scores.restype = None
        lib.order_paths.argtypes = [ctypes.POINTER(ctypes.c_char_p),
                                     ctypes.POINTER(ctypes.c_size_t), ctypes.c_size_t,
                                     ctypes.POINTER(ctypes.c_uint64)]
        lib.order_paths.restype = None
        _LIBRARY = lib
    return _LIBRARY


def total_key(value):
    bits, = struct.unpack('<Q', struct.pack('<d', value))
    return ((~bits) & ((1 << 64) - 1)) if bits >> 63 else (bits ^ (1 << 63))


def by_score(entries, now):
    if len(entries) < 2:
        return
    if len(entries) <= 32:
        entries.sort(key=lambda entry: total_key(entry.score(now)))
        return
    count = len(entries)
    values = (ctypes.c_double * count)(*(entry.score(now) for entry in entries))
    result = (ctypes.c_uint64 * count)()
    _library().order_scores(values, count, result)
    entries[:] = [entries[i] for i in result]


def by_path(entries):
    if len(entries) < 2:
        return
    if len(entries) <= 32:
        entries.sort(key=lambda entry: entry.path)
        return
    strings = [entry.path.encode('utf-8') for entry in entries]
    count = len(entries)
    pointers = (ctypes.c_char_p * count)(*strings)
    lengths = (ctypes.c_size_t * count)(*(len(s) for s in strings))
    result = (ctypes.c_uint64 * count)()
    _library().order_paths(pointers, lengths, count, result)
    entries[:] = [entries[i] for i in result]
