def total_key(value):
    bits, = struct.unpack('<Q', struct.pack('<d', value))
    return ((~bits) & ((1 << 64) - 1)) if bits >> 63 else (bits ^ (1 << 63))


def by_score(entries, now):
    if len(entries) < 2:
        return
    if len(entries) <= 32:
        entries.sort(key=lambda entry: total_key(entry.score(now)))
        return
    count = len(entries)
    values = (ctypes.c_double * count)(*(entry.score(now) for entry in entries))
    result = (ctypes.c_uint64 * count)()
    _library().order_scores(values, count, result)
    entries[:] = [entries[i] for i in result]


def by_path(entries):
    if len(entries) < 2:
        return
    if len(entries) <= 32:
        entries.sort(key=lambda entry: entry.path)
        return
    strings = [entry.path.encode('utf-8') for entry in entries]
    count = len(entries)
    pointers = (ctypes.c_char_p * count)(*strings)
    lengths = (ctypes.c_size_t * count)(*(len(s) for s in strings))
    result = (ctypes.c_uint64 * count)()
    _library().order_paths(pointers, lengths, count, result)
    entries[:] = [entries[i] for i in result]
