"""Terminal styling for help and argument diagnostics."""
import os
import re
import sys

RESET = '\x1b[0m'
BOLD = '\x1b[1m'
HEADING = '\x1b[1m\x1b[4m'
GREEN = '\x1b[32m'
YELLOW = '\x1b[33m'


def enabled(stream='stderr'):
    if os.environ.get('NO_COLOR'):
        return False
    if os.environ.get('CLICOLOR_FORCE'):
        return True
    handle = sys.stderr if stream == 'stderr' else sys.stdout
    return handle.isatty() and os.environ.get('TERM') != 'dumb' and os.environ.get('CLICOLOR') != '0'


def usage(text, prefix):
    if text.startswith(prefix):
        text = BOLD + prefix + RESET + text[len(prefix):]
    # Placeholders are not emphasized; option names are.
    return re.sub(r'(?<= )(--[a-z-]+)(?= |$)', lambda m: BOLD + m[1] + RESET, text)


def help_text(text, prefix):
    lines = text.splitlines(keepends=True)
    section = ''
    for index, line in enumerate(lines):
        stripped = line.rstrip('\n')
        if index == 0 and stripped.startswith('zoxide'):
            lines[index] = HEADING + stripped + '\x1b[22m\x1b[24m\n'
        elif stripped == 'Environment variables:':
            section = 'env'
            lines[index] = HEADING + stripped + '\x1b[22m\x1b[24m\n'
        elif stripped in ('Usage:', 'Commands:', 'Arguments:', 'Options:'):
            section = stripped[:-1]
            lines[index] = HEADING + stripped + RESET + '\n'
        elif line.startswith('Usage: '):
            section = 'Usage'
            lines[index] = HEADING + 'Usage:' + RESET + ' ' + usage(line[7:], prefix)
        elif line.strip():
            if section == 'Usage':
                lines[index] = '  ' + usage(line[2:], prefix)
            elif section == 'Commands':
                lines[index] = re.sub(r'^(\s+)(\S+)', lambda m: m[1] + BOLD + m[2] + RESET, line)
            elif section == 'Options':
                lines[index] = re.sub(r'(?<!\w)(--?[A-Za-z][a-z-]*)', lambda m: BOLD + m[1] + RESET, line)
            elif section == 'env':
                lines[index] = re.sub(r'^(\s+)(_ZO_\w+)', lambda m: m[1] + BOLD + m[2] + '\x1b[22m', line)
    return ''.join(lines)


def diagnostic(message):
    lines = message.split('\n')
    if lines[0].startswith(('invalid value ', 'unexpected value ')):
        first = True

        def quoted(match):
            nonlocal first
            style = YELLOW if first else BOLD
            first = False
            return "'" + style + match[1] + RESET + "'"
        lines[0] = re.sub(r"'([^']*)'", quoted, lines[0])
    else:
        lines[0] = re.sub(r"'([^']*)'", lambda m: "'" + YELLOW + m[1] + RESET + "'", lines[0])
    for i in range(1, len(lines)):
        line = lines[i]
        if line.startswith('  [possible values: ') and line.endswith(']'):
            values = line[20:-1].split(', ')
            lines[i] = '  [possible values: ' + ', '.join(GREEN + value + RESET for value in values) + ']'
        elif lines[0].startswith('the following required arguments'):
            lines[i] = '  ' + GREEN + line[2:] + RESET
    return '\n'.join(lines)


def tip(text):
    first = True

    def quoted(match):
        nonlocal first
        style = YELLOW if first and text.startswith('to pass ') else GREEN
        first = False
        return "'" + style + match[1] + RESET + "'"
    return '  ' + GREEN + 'tip:' + RESET + ' ' + re.sub(r"'([^']*)'", quoted, text)
PY
